def decide(request):
    'Return the decision for one support request.'
    # Row 1: the item was damaged or the wrong item arrived.
    if request['reason'] in ('damaged', 'wrong_item'):
        return 'approve'
    # Row 2: the delivery was late, so a person should look at it.
    if request['reason'] == 'late_delivery':
        return 'review'
    # Row 3: email requests are declined before any amount is checked.
    if request['channel'] == 'email':
        return 'decline'
    # Row 4: any other request for 50 or more needs a person too.
    if request['amount'] >= 50:
        return 'review'
    # Row 5: everything else is approved straight away.
    return 'approve'
